// Generates prisma/schema.production.prisma from the SQLite schema by swapping
// only the datasource provider. Keeping one source of truth means the two can't
// drift — never edit the generated file by hand.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const src = path.join(here, "..", "prisma", "schema.prisma");
const out = path.join(here, "..", "prisma", "schema.production.prisma");

const schema = readFileSync(src, "utf8");

if (!/provider\s*=\s*"sqlite"/.test(schema)) {
  throw new Error(`Expected a sqlite datasource in ${src}. Did the schema change?`);
}

const header = `// GENERATED by scripts/gen-prod-schema.mjs — do not edit.\n// Source of truth: prisma/schema.prisma\n\n`;
const prod = header + schema.replace(/provider\s*=\s*"sqlite"/, 'provider = "postgresql"');

writeFileSync(out, prod);
console.log(`[schema] wrote ${path.relative(process.cwd(), out)} (postgresql)`);
